void dfs1(int u, vector<vector<int>>& adj, vector<bool>& vis, vector<int>& order) {
    vis[u] = true;
    for (int v : adj[u]) if (!vis[v]) dfs1(v, adj, vis, order);
    order.push_back(u);                 // record finish order
}
void dfs2(int u, vector<vector<int>>& radj, vector<bool>& vis, vector<int>& comp, int c) {
    vis[u] = true; comp[u] = c;
    for (int v : radj[u]) if (!vis[v]) dfs2(v, radj, vis, comp, c);
}
int kosaraju(int n, vector<vector<int>>& adj, vector<vector<int>>& radj) {
    vector<bool> vis(n, false); vector<int> order;
    for (int i = 0; i < n; i++) if (!vis[i]) dfs1(i, adj, vis, order);
    fill(vis.begin(), vis.end(), false);
    vector<int> comp(n, -1); int c = 0;
    for (int i = n - 1; i >= 0; i--)     // reverse finish order
        if (!vis[order[i]]) { dfs2(order[i], radj, vis, comp, c); c++; }
    return c;                            // number of SCCs
}

