def kosaraju(n, adj, radj):
    vis = [False] * n
    order = []
    def dfs1(u):
        vis[u] = True
        for v in adj[u]:
            if not vis[v]:
                dfs1(v)
        order.append(u)                 # record finish order
    for i in range(n):
        if not vis[i]:
            dfs1(i)
    vis = [False] * n
    comp = [-1] * n
    def dfs2(u, c):
        vis[u] = True
        comp[u] = c
        for v in radj[u]:
            if not vis[v]:
                dfs2(v, c)
    c = 0
    for u in reversed(order):           # reverse finish order
        if not vis[u]:
            dfs2(u, c)
            c += 1
    return c                            # number of SCCs

