function kosaraju(n, adj, radj) {
  const vis = new Array(n).fill(false);
  const order = [];
  const dfs1 = (u) => { vis[u] = true; for (const v of adj[u]) if (!vis[v]) dfs1(v); order.push(u); };  // finish order
  for (let i = 0; i < n; i++) if (!vis[i]) dfs1(i);
  vis.fill(false);
  const comp = new Array(n).fill(-1);
  let c = 0;
  const dfs2 = (u) => { vis[u] = true; comp[u] = c; for (const v of radj[u]) if (!vis[v]) dfs2(v); };
  for (let i = n - 1; i >= 0; i--)      // reverse finish order
    if (!vis[order[i]]) { dfs2(order[i]); c++; }
  return c;                            // number of SCCs
}
